p = list(map(int, input().split()))
def kadane_max(a):
    best = cur = a[0]
    for x in a[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best
def kadane_min(a):
    best = cur = a[0]
    for x in a[1:]:
        cur = min(x, cur + x)
        best = min(best, cur)
    return best
max_straight = kadane_max(p)
if max_straight < 0:
    print(max_straight)
else:
    print(max(max_straight, sum(p) - kadane_min(p)))

